import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.ChTAMbUy.js";const c=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"development/admin/upgrading.md","filePath":"versions/development/admin/upgrading.md","lastUpdated":1795112498000}'),r={name:"development/admin/upgrading.md"};function n(l,e,o,p,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>Upgrade prokube with the release-specific instructions for the target version. Do not use backup and restore as a version-upgrade mechanism unless a release explicitly documents that path.</p><h2 id="before-upgrading" tabindex="-1">Before Upgrading <a class="header-anchor" href="#before-upgrading" aria-label="Permalink to &quot;Before Upgrading&quot;">​</a></h2><p>Prepare the upgrade as an operational change:</p><ul><li>read the release notes and migration notes for every skipped version;</li><li>verify the target Kubernetes version and component compatibility;</li><li>confirm a recent successful backup and restore procedure;</li><li>check cluster health, node capacity, and storage capacity;</li><li>pause or drain user workloads where required by the release notes;</li><li>identify the GitOps repository, branch, and Argo CD applications that control the deployment.</li></ul><h2 id="gitops-managed-deployments" tabindex="-1">GitOps-Managed Deployments <a class="header-anchor" href="#gitops-managed-deployments" aria-label="Permalink to &quot;GitOps-Managed Deployments&quot;">​</a></h2><p>In GitOps-managed deployments, upgrade by changing the authoritative deployment configuration, not by patching live resources manually.</p><p>Typical flow:</p><ol><li>Create an upgrade branch from the deployment repository.</li><li>Apply the release-specific changes.</li><li>Review generated manifests and environment overlays.</li><li>Merge or push through the deployment&#39;s normal approval path.</li><li>Refresh and sync the affected Argo CD applications.</li><li>Watch reconciliation, pods, jobs, and application health until the platform is stable.</li></ol><p>Avoid force pushes and live hotfixes unless the deployment runbook explicitly requires them and the rollback path is clear.</p><h2 id="kubernetes-and-node-upgrades" tabindex="-1">Kubernetes and Node Upgrades <a class="header-anchor" href="#kubernetes-and-node-upgrades" aria-label="Permalink to &quot;Kubernetes and Node Upgrades&quot;">​</a></h2><p>Kubernetes or node upgrades can affect stateful workloads and <code>ReadWriteOnce</code> volumes. Before draining nodes, check for Labs, database pods, MinIO pods, MLflow components, and model-serving workloads with local or node-bound storage.</p><p>If a pod cannot move during a drain, inspect:</p><ul><li>PVC access mode and topology;</li><li>pod disruption budgets;</li><li>node selectors and affinities;</li><li>GPU or local-storage constraints;</li><li>controller reconciliation status.</li></ul><p>Do not delete stuck stateful pods or volumes to force progress unless the storage and application recovery implications are understood.</p><h2 id="after-upgrading" tabindex="-1">After Upgrading <a class="header-anchor" href="#after-upgrading" aria-label="Permalink to &quot;After Upgrading&quot;">​</a></h2><p>Validate user-facing and admin paths:</p><ul><li>login and workspace selection;</li><li>Labs start/stop and volume mounting;</li><li>file storage browser and S3 access;</li><li>Pipelines submission and run logs;</li><li>MLflow login, tracking, and artifact access;</li><li>Model Serving deployment and endpoint testing;</li><li>System Status, Grafana, Prometheus, Loki, and Alertmanager;</li><li>backup jobs and monitoring alerts.</li></ul><h2 id="upgrading-to-prokube-1-10" tabindex="-1">Upgrading to prokube 1.10 <a class="header-anchor" href="#upgrading-to-prokube-1-10" aria-label="Permalink to &quot;Upgrading to prokube 1.10&quot;">​</a></h2><p>Check the following when upgrading from prokube 1.9 or earlier.</p><h3 id="prefixed-mcp-tool-names" tabindex="-1">Prefixed MCP Tool Names <a class="header-anchor" href="#prefixed-mcp-tool-names" aria-label="Permalink to &quot;Prefixed MCP Tool Names&quot;">​</a></h3><p>From prokube 1.10, federated MCP tool and prompt names always carry the MCP server&#39;s name as a prefix, also in workspaces with a single MCP server. See <a href="./../agentops/agent_gateway.html#mcp-federation-and-tool-selection">MCP Federation and Tool Selection</a>. prokube 1.9 and earlier exposed bare tool names in workspaces with a single MCP server. Before upgrading:</p><ul><li>confirm that the installed Agent Gateway CRDs and runtime are version 1.4 or newer;</li><li>schedule the upgrade with the owners of Agents, prompts, and clients that reference tools by bare name, so they can switch to the prefixed names;</li><li>plan rollbacks with the same owners: a rollback restores bare names in workspaces with a single MCP server, so their references must be changed back.</li></ul><h3 id="toolhive-metrics-for-existing-mcp-servers" tabindex="-1">ToolHive Metrics for Existing MCP Servers <a class="header-anchor" href="#toolhive-metrics-for-existing-mcp-servers" aria-label="Permalink to &quot;ToolHive Metrics for Existing MCP Servers&quot;">​</a></h3><p>From prokube 1.10, the prokube UI labels the MCP servers it deploys with <code>prokube.ai/mcp-metrics</code>, and labelled servers report <a href="./../agentops/mcp_servers.html#server-metrics-and-traffic">ToolHive metrics</a>. Servers deployed through the UI in prokube 1.9 and earlier have no ToolHive metrics until they are labelled. Adding the label restarts the server&#39;s proxy once, which drops open MCP sessions.</p><p>To label all servers that reference the prokube-managed <code>pkui-mcp-telemetry</code> config:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcpservers.toolhive.stacklok.dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.items[] | select(.spec.telemetryConfigRef.name == &quot;pkui-mcp-telemetry&quot;) | [.metadata.namespace, .metadata.name] | @tsv&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  while</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IFS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> namespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcpservers.toolhive.stacklok.dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$namespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;spec&quot;:{&quot;resourceOverrides&quot;:{&quot;proxyDeployment&quot;:{&quot;podTemplateMetadataOverrides&quot;:{&quot;labels&quot;:{&quot;prokube.ai/mcp-metrics&quot;:&quot;true&quot;}}}}}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  done</span></span></code></pre></div><h3 id="gateway-usage-right-after-upgrading" tabindex="-1">Gateway Usage Right After Upgrading <a class="header-anchor" href="#gateway-usage-right-after-upgrading" aria-label="Permalink to &quot;Gateway Usage Right After Upgrading&quot;">​</a></h3><p>Gateway access logs written before the upgrade to prokube 1.10 do not separate token calls from calls without valid credentials. Until those logs age out, 10 days after the upgrade by default, <a href="./../platform/gateway_usage.html#sources">Gateway Usage</a> can count some token calls as <strong>Calls without valid credentials</strong>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./backup_restore.html">Backup and Restore</a></li><li><a href="./installation.html">Installation Planning</a></li><li><a href="./operations_runbooks.html">Operations Runbooks</a></li></ul>`,31)])])}const k=a(r,[["render",n]]);export{c as __pageData,k as default};
